typedef FineCoordinator::Controller<Session> Fine;
static FineStore::Identity Identity(){FineStore::Identity i={};i.sourceEpoch=0x100000007ULL;i.materialGeneration=0x700000008ULL;for(unsigned n=0;n<32;++n){i.baseSha[n]=BYTE(n+1);i.sourceCatalogSha[n]=BYTE(n+33);i.materialSha[n]=BYTE(n+65);}return i;}
static FineJob::Demand Demand(const SourceReceipts::Scope&s){FineJob::Demand d={};d.scope=s;d.revision=0x100000009ULL;d.view.stamp.source=s.sourceEpoch;d.view.stamp.material=Identity().materialGeneration;d.view.world.x=d.view.world.z=-14336;d.view.world.w=512;d.view.world.h=256;d.view.screenWidth=512;d.view.screenHeight=256;return d;}
static FineStore::Config Config(const wchar_t*parent,const wchar_t*leaf){FineStore::Config c={};C(FineStore::Configure(c,parent,(std::wstring(parent)+L"\\"+leaf).c_str()),"new-only owned cache directory config");return c;}
static WorldCohort::Job FineNativeJob(const FineJob::Plan&p,const FineJob::Demand&now){WorldCohort::Job base;InitJob(base,now.scope);FineJob::Snapshot snapshot={p.demand.view.stamp,base.material};FineJob::Settings settings={10000,20000,-10000,0};WorldCohort::Job out;C(FineJob::MakeJob(p,0,now,snapshot,settings,base.shaders,base.heightPath,out),"real canonical origin-anchored K2 job");return out;}
static int Tick(Fine&f,ID3D11Device*d,const FineJob::Demand&now,const FineStore::Identity&id,const FineCoordinator::Residency&r,const FineStore::Ledger&cpu,int wanted=0){DWORD start=GetTickCount();while(GetTickCount()-start<60000){int result=f.Tick(true,d,now,id,r,cpu);if(result<0){std::fprintf(stderr,"coordinator error%08x\n",unsigned(f.Error()));C(false,"coordinator progression");}if((wanted&&result==wanted)||(!wanted&&f.Ready()))return result;Sleep(1);}C(false,"bounded coordinator progression deadline");return -1;}
static void Baseline(const WorldCohort::Job&job,std::vector<BYTE>(&planes)[2][3]){Provider provider;WorldStream::Controller<Provider>*stream=new WorldStream::Controller<Provider>(provider);C(stream->Start()==S_OK,"sequential actual-production baseline starts");WorldBank::Ledger ledger={};while(stream->State()==WorldStream::Booting){C(SUCCEEDED(stream->Pump(false,NULL,job.scope,ledger)),"baseline boot");Sleep(1);}AtlasView::Com<ID3D11Device>d;AtlasView::Com<ID3D11DeviceContext>ctx;C(SUCCEEDED(D3D11CreateDevice(NULL,D3D_DRIVER_TYPE_WARP,NULL,0,NULL,0,D3D11_SDK_VERSION,&d.p,NULL,&ctx.p)),"baseline WARP");
 for(unsigned n=0;n<2;++n){WorldStream::Job single=Single(job,n);WorldStream::CapturedSources*tokens=new WorldStream::CapturedSources;Tokens(provider,single,*tokens);C(SUCCEEDED(stream->Submit(true,single,*tokens,single.scope)),"baseline fine job admitted");DWORD start=GetTickCount();while(stream->State()!=WorldStream::Complete&&GetTickCount()-start<60000){C(SUCCEEDED(stream->Pump(true,d.p,single.scope,ledger)),"actual baseline source/raster/query/acceptance");Sleep(1);}C(stream->Result(true,single.scope,single.frame)!=NULL,"baseline accepted fine view");for(unsigned p=0;p<3;++p){const BYTE*data=stream->Plane(p,true,single.scope,single.frame);planes[n][p].assign(data,data+256*256*(p?4:8));}stream->ReleaseResult();delete tokens;}
 stream->Shutdown();C(stream->State()==WorldStream::Stopped&&!stream->OwnedGpuBytes(),"baseline producer released before coordinator phase");delete stream;}
static void Texture(ID3D11Device*d,unsigned side,AtlasView::Com<ID3D11Texture2D>&out){D3D11_TEXTURE2D_DESC t={};t.Width=t.Height=side;t.ArraySize=t.MipLevels=t.SampleDesc.Count=1;t.Format=DXGI_FORMAT_R8G8B8A8_UNORM;t.Usage=D3D11_USAGE_DEFAULT;t.BindFlags=D3D11_BIND_SHADER_RESOURCE;C(SUCCEEDED(d->CreateTexture2D(&t,NULL,&out.p)),"real retained viewer/pending/retired test resource");}
